#include "unity.h"

static bool isAdcRawValid(int raw) {
  return raw >= 0 && raw <= 4095;
}

TEST_CASE("ADC raw values stay within the 12-bit range", "[sensor]") {
  TEST_ASSERT_TRUE(isAdcRawValid(0));
  TEST_ASSERT_TRUE(isAdcRawValid(4095));
  TEST_ASSERT_FALSE(isAdcRawValid(-1));
  TEST_ASSERT_FALSE(isAdcRawValid(4096));
}
